class ValidationError extends Error {
  constructor(field, message) {
    super(message);
    this.name = "ValidationError";
    this.field = field;
  }
}

function validateAge(age) {
  if (typeof age !== "number") {
    throw new ValidationError("age", "Age must be a number");
  }
  if (age < 0 || age > 150) {
    throw new ValidationError("age", "Age must be 0-150");
  }
}

try {
  validateAge(-5);
} catch (e) {
  if (e instanceof ValidationError) {
    console.log(e.field + ": " + e.message);
  }
}

class ApiError extends Error {
  constructor(status, endpoint, message) {
    super(message);
    this.name = "ApiError";
    this.status = status;
    this.endpoint = endpoint;
    this.retryable = status >= 500;
  }
}

async function fetchData(url) {
  let response = await fetch(url);
  if (!response.ok) {
    throw new ApiError(response.status, url, `HTTP ${response.status}`);
  }
  return response.json();
}

try {
  await fetchData("/api/users");
} catch (e) {
  if (e instanceof ApiError && e.retryable) {
    console.log("Retrying...");
  } else {
    console.error(e.message);
  }
}

async function loadUser(id) {
  try {
    let response = await fetch(`/api/users/${id}`);
    if (!response.ok) throw new Error("HTTP " + response.status);
    return await response.json();
  } catch (originalError) {
    throw new Error("Failed to load user", { cause: originalError });
  }
}

try {
  await loadUser(1);
} catch (e) {
  console.log(e.message);       // "Failed to load user"
  console.log(e.cause.message); // "HTTP 404" (original error)
  console.log(e.cause);         // full original Error object
}

